SELECT x.record_id AS GX_Record_ID, x.run_id AS GX_Run_ID, x.run_key AS GX_Run_Key, CAST(x.rule_id AS INTEGER) AS GX_Rule_ID, x.rule_nm AS GX_Rule_Nm, x.rule_group AS GX_Rule_Group, x.rule_variant AS GX_Rule_Variant, x.database_name AS GX_Database_Name, x.src_tbl_nm AS GX_Src_Tbl_Nm, x.project_name AS GX_Project_Name, x.process_name AS GX_Process_Name, x.element_name AS GX_Element_Name, x.source_name AS GX_Source_Name, x.src_key_value AS GX_Src_Key_Value, REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_SUBSTR(x.src_key_value, '(^|[|])SRC_DATA_KEY=[^|]*', 1, 1, 'i'), '^.*=', '', 1, 0, 'c'), '[.]0*$', '', 1, 0, 'c') AS GX_Src_Data_Key, x.dgr_nbr AS GX_Dgr_Nbr, r.severity AS GX_Severity, r.issue_category_name AS GX_Issue_Category, r.business_rule AS GX_Business_Rule, x.universe_version AS GX_Universe_Version, x.run_type AS GX_Run_Type, x.batch_schedule AS GX_Batch, x.exception_flag AS GX_Exception_Flag, x.exception_approver AS GX_Exception_Approver, x.etl_load_dt AS GX_Load_Dt, x.load_datetime AS GX_Load_Dtts, x.last_updated_by AS GX_Last_Updated_By, x.last_updated_datetime AS GX_Last_Updated_Dtts, CASE WHEN UPPER(TRIM(x.exception_flag)) = 'OPEN' THEN 1 ELSE 0 END AS GX_Open_Ind, CAST(1 AS INTEGER) AS GX_Exception_Cnt
FROM HSABC_V.gre_exceptions x
LEFT JOIN HSABC_V.gre_rules r ON r.rule_id = x.rule_id
WHERE x.etl_is_curr_ind = 'Y' AND UPPER(TRIM(x.rule_group)) LIKE 'ODAG1%'
